<main class="mx-auto max-w-7xl px-4 py-8 sm:px-6 lg:px-8">
  <div><p class="text-[10px] font-black uppercase tracking-[.2em] text-violet-300">Player care</p><h1 class="mt-2 text-3xl font-black">Support inbox</h1><p class="mt-2 text-sm text-slate-400">Handle tournament, account and wallet questions. Never ask players for passwords or payment credentials.</p></div>
  <form method="get" class="glass-card mt-5 flex flex-wrap items-end gap-3 rounded-2xl p-4"><input type="hidden" name="page" value="admin-support"><label class="min-w-48 flex-1 text-xs font-bold text-slate-400">Search<input class="form-control mt-2" name="q" maxlength="80" value="<?= h($search) ?>" placeholder="Email, subject, message"></label><label class="min-w-36 text-xs font-bold text-slate-400">Status<select class="form-control mt-2" name="status"><option value="all">All statuses</option><?php foreach(['open','in_progress','resolved','closed'] as $status): ?><option value="<?= h($status) ?>" <?= $statusFilter===$status?'selected':'' ?>><?= h(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select></label><button class="btn-primary rounded-xl px-5 py-3 text-sm font-black">Filter</button></form>
  <div class="mt-5 space-y-3"><?php if(!$requests): ?><div class="glass-card rounded-2xl p-8 text-center text-sm text-slate-500">No support requests found.</div><?php endif; ?><?php foreach($requests as $item): ?><article class="glass-card rounded-2xl p-5"><div class="flex flex-wrap items-start justify-between gap-4"><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class="font-black"><?= h($item['subject']) ?></h2><span class="badge <?= $item['status']==='resolved'?'badge-open':($item['status']==='open'?'badge-soon':'badge-closed') ?>"><?= h($item['status']) ?></span></div><p class="mt-1 text-[10px] text-slate-500"><?= h($item['contact_email']) ?> · #<?= h($item['id']) ?> · <?= h(date('d M Y · g:i A',strtotime((string)$item['created_at'].' UTC'))) ?></p><p class="mt-4 whitespace-pre-line text-sm leading-6 text-slate-300"><?= h($item['message']) ?></p></div><form method="post" action="<?= h(app_url('index.php?action=admin-support-status')) ?>" class="min-w-44 space-y-2"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= h($item['id']) ?>"><label class="sr-only" for="support-status-<?= h($item['id']) ?>">Update support status</label><select class="form-control !py-2 text-xs" id="support-status-<?= h($item['id']) ?>" name="status"><?php foreach(['open','in_progress','resolved','closed'] as $status): ?><option value="<?= h($status) ?>" <?= $item['status']===$status?'selected':'' ?>><?= h(ucwords(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select><button class="w-full rounded-lg border border-white/10 px-3 py-2 text-[10px] font-bold">Update status</button></form></div></article><?php endforeach; ?></div>
  <?php if($pageCount>1): ?><nav class="mt-5 flex gap-2"><?php for($n=1;$n<=$pageCount;$n++): ?><a class="rounded-lg border px-3 py-2 text-xs <?= $n===$pageNumber?'border-violet-400/50 text-violet-200':'border-white/10 text-slate-400' ?>" href="<?= h(app_url('index.php?'.http_build_query(['page'=>'admin-support','q'=>$search,'status'=>$statusFilter,'p'=>$n]))) ?>"><?= h($n) ?></a><?php endfor; ?></nav><?php endif; ?>
</main>
